function __parseCookie(raw) {
    var kv = {};
    var segs = String(raw).split(';');
    for (var i = 0; i < segs.length; i++) {
        var p = segs[i];
        var eq = p.indexOf('=');
        if (eq > 0) kv[p.substring(0, eq).trim()] = p.substring(eq + 1).trim();
    }
    return kv;
}

function login() {
    var info = source.getLoginInfoMap();
    if (!info) { java.toast('请先输入'); return; }
    var raw = String(info.get('Cookie') || '').trim();
    if (!raw) { java.toast('请粘贴完整Cookie'); return; }
    var kv = __parseCookie(raw);
    if (!kv['ltoken_v2'] || !kv['ltuid_v2']) { java.toast('Cookie缺少ltoken_v2或ltuid_v2'); return; }
    if (!kv['ltmid_v2']) { java.toast('警告:缺少ltmid_v2会话标识,可能仍登录失效'); }
    source.put('mhyCookie', raw);
    source.put('ltoken', kv['ltoken_v2']);
    source.put('ltuid', kv['ltuid_v2']);
    java.toast('保存成功');
    doCheckLogin();
}

function logout() {
    source.put('mhyCookie', '');
    source.put('ltoken', '');
    source.put('ltuid', '');
    java.toast('已清除登录信息');
}

function __md5(s) {
    try {
        var md = new Packages.java.security.MessageDigest.getInstance('MD5');
        var b = Packages.java.lang.String(s).getBytes('UTF-8');
        md.update(b);
        var d = md.digest();
        var sb = new Packages.java.lang.StringBuilder();
        for (var i = 0; i < d.length; i++) {
            var x = d[i] & 0xFF;
            if (x < 16) sb.append('0');
            sb.append(Packages.java.lang.Integer.toHexString(x));
        }
        return String(sb.toString()).toLowerCase();
    } catch(e) { return ''; }
}

function __ds() {
    var t = Math.floor(Date.now() / 1000).toString();
    var r = Math.floor(Math.random() * 900000 + 100000).toString();
    return t + ',' + r + ',' + __md5('salt=DlOUwIupfU6YespEUWDJmXtutuXV6owG&t=' + t + '&r=' + r);
}

function __auth() {
    var full = '', ltoken = '', ltuid = '';
    try {
        if (typeof source !== 'undefined' && source) {
            full = String(source.get('mhyCookie') || '');
            ltoken = String(source.get('ltoken') || '');
            ltuid = String(source.get('ltuid') || '');
        }
    } catch(e) {}
    return {full: full, ltoken: ltoken, ltuid: ltuid};
}

function __cookie(auth) {
    if (auth && auth.full) return auth.full;
    if (auth && auth.ltoken && auth.ltuid) {
        return 'ltoken_v2=' + auth.ltoken + '; ltuid_v2=' + auth.ltuid +
               '; account_id=' + auth.ltuid + '; account_id_v2=' + auth.ltuid;
    }
    return '';
}

function __http(url, method, body, auth, extra) {
    var headers = {
        'Accept': 'application/json, text/plain, */*',
        'x-rpc-channel': 'miyousheluodi',
        'Origin': 'https://webstatic.mihoyo.com',
        'x-rpc-app_version': '2.99.1',
        'User-Agent': 'Mozilla/5.0 (Linux; Android 12) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/103.0.5060.129 Mobile Safari/537.36 miHoYoBBS/2.99.1',
        'x-rpc-client_type': '5',
        'X-Requested-With': 'com.mihoyo.hyperion',
        'x-rpc-device_id': '5b814ba0-99c3-4483-0905-0007f556ee3a'
    };
    if (extra) for (var k in extra) headers[k] = extra[k];
    if (method === 'POST') headers['Content-Type'] = 'application/json';
    var c = __cookie(auth);
    if (c) headers['Cookie'] = c;
    var opts = {method: method, headers: headers};
    if (body) opts.body = body;
    return java.ajax(url + ',' + JSON.stringify(opts));
}

function __gameConfig() {
    return {
        '原神': {biz: 'hk4e_cn', api: 'https://api-takumi.mihoyo.com/event/luna/hk4e/', act: 'e202311201442471', signgame: 'hk4e', ref: 'https://webstatic.mihoyo.com/bbs/event/signin/hk4e/index.html'},
        '崩坏3': {biz: 'bh3_cn', api: 'https://api-takumi.mihoyo.com/event/luna/bh3/', act: 'e202306201626331', signgame: 'bh3', ref: 'https://webstatic.mihoyo.com/bbs/event/signin/bh3/index.html'},
        '崩坏星穹铁道': {biz: 'hkrpg_cn', api: 'https://api-takumi.mihoyo.com/event/luna/hkrpg/', act: 'e202304121516551', signgame: 'hkrpg', ref: 'https://webstatic.mihoyo.com/bbs/event/signin/hkrpg/index.html'},
        '绝区零': {biz: 'nap_cn', api: 'https://act-nap-api.mihoyo.com/event/luna/zzz/', act: 'e202406242138391', signgame: 'zzz', ref: 'https://webstatic.mihoyo.com/bbs/event/signin/zzz/index.html'}
    };
}

function __roles(auth, biz) {
    var r = __http('https://api-takumi.mihoyo.com/binding/api/getUserGameRolesByCookie?game_biz=' + biz, 'GET', null, auth, {'DS': __ds()});
    if (!r) return [];
    try { var d = JSON.parse(r); return (d.retcode === 0 && d.data && d.data.list) ? d.data.list : []; } catch(e) { return []; }
}

function __signInfo(auth, cfg, region, uid) {
    var r = __http(cfg.api + 'info?lang=zh-cn&act_id=' + cfg.act + '&region=' + region + '&uid=' + uid, 'GET', null, auth, {
        'DS': __ds(), 'x-rpc-signgame': cfg.signgame, 'Referer': cfg.ref
    });
    if (!r) return null;
    try { return JSON.parse(r); } catch(e) { return null; }
}

function __sign(auth, cfg, region, uid) {
    var body = JSON.stringify({act_id: cfg.act, region: String(region), uid: String(uid), lang: 'zh-cn'});
    var r = __http(cfg.api + 'sign', 'POST', body, auth, {
        'DS': __ds(), 'x-rpc-signgame': cfg.signgame, 'Referer': cfg.ref
    });
    if (!r) return '-1,无响应';
    try {
        var d = JSON.parse(r);
        if (d.retcode === 0 && d.data && d.data.success === 0) return '0,签到成功';
        if (d.retcode === 0 && d.data && d.data.success === 1) return '1,触发验证码,需手动签到';
        if (d.retcode === -5003) return '0,今日已签到';
        if (d.retcode === -100) return '-1,登录失效,请重新登录';
        if (d.retcode === -500001) return '-1,请求校验失败';
        return d.retcode + ',' + (d.message || '签到失败');
    } catch(e) { return '-1,解析失败'; }
}

function doCheckLogin() {
    var auth = __auth();
    if (!auth.ltoken && !auth.full) { java.toast('未配置Token'); return; }
    java.toast('验证中...');
    var roles = __roles(auth, 'hk4e_cn');
    if (roles && roles.length > 0) {
        var names = [];
        for (var i = 0; i < roles.length; i++) names.push(roles[i].nickname || '角色');
        java.toast('登录有效: ' + names.join(','));
    } else {
        java.toast('登录失效,请重新获取完整Cookie');
    }
}

function doQueryStatus() {
    var auth = __auth();
    if (!auth.ltoken && !auth.full) { java.toast('未配置Token'); return; }
    java.toast('查询中...');
    var games = ['原神', '崩坏3', '崩坏星穹铁道', '绝区零'];
    var CFG = __gameConfig();
    var results = [];
    for (var i = 0; i < games.length; i++) {
        var name = games[i];
        var cfg = CFG[name];
        if (!cfg) continue;
        var roles = __roles(auth, cfg.biz);
        if (!roles || roles.length === 0) { results.push(name + ': 未绑定'); continue; }
        for (var j = 0; j < roles.length; j++) {
            var r = roles[j];
            var info = __signInfo(auth, cfg, r.region, r.game_uid || r.uid);
            if (info && info.retcode === 0 && info.data) {
                var d = info.data;
                var status = d.is_sign ? '已签到' : '未签到';
                results.push(name + ' [' + (r.nickname || '') + ']: ' + status + ' 连续' + d.total_sign_day + '天');
            } else {
                results.push(name + ' [' + (r.nickname || '') + ']: 查询失败');
            }
        }
    }
    __show(results.join(String.fromCharCode(10)));
}

function doManual() {
    var auth = __auth();
    if (!auth.ltoken && !auth.full) { java.toast('未配置Token'); return; }
    java.toast('开始签到...');
    var games = ['原神', '崩坏3', '崩坏星穹铁道', '绝区零'];
    var CFG = __gameConfig();
    var results = [];
    for (var i = 0; i < games.length; i++) {
        var name = games[i];
        var cfg = CFG[name];
        if (!cfg) continue;
        var roles = __roles(auth, cfg.biz);
        if (!roles || roles.length === 0) { results.push('[' + name + '] 未绑定,跳过'); continue; }
        for (var j = 0; j < roles.length; j++) {
            var r = roles[j];
            var rc = __sign(auth, cfg, r.region, r.game_uid || r.uid);
            var parts = rc.split(',');
            results.push('[' + name + ' ' + (r.nickname || '') + '] ' + parts[1]);
        }
    }
    __show(results.join(String.fromCharCode(10)));
}

function doHelp() {
    var helpText = '【获取Cookie方法(必须完整)】' + String.fromCharCode(10) + '1. 浏览器打开 bbs.mihoyo.com 并登录' + String.fromCharCode(10) + '2. F12控制台输入 document.cookie 回车' + String.fromCharCode(10) + '3. 复制全部输出(一整段,不要删减!)' + String.fromCharCode(10) + '4. 其中必须包含: ltoken_v2 / ltuid_v2 / ltmid_v2' + String.fromCharCode(10) + '   (ltmid_v2是会话配对标识,缺失会登录失效)' + String.fromCharCode(10) + '5. 整段粘贴到登录界面Cookie框' + String.fromCharCode(10) + String.fromCharCode(10) + '【定时设置】' + String.fromCharCode(10) + '推荐 cron: 0 0 * * * (每天0点)' + String.fromCharCode(10) + String.fromCharCode(10) + '支持: 原神/崩坏3/星穹铁道/绝区零';
    java.copyText(helpText);
    java.longToast('帮助已复制到剪贴板');
}

function __show(text) {
    try { java.longToast(text); } catch(e) { try { java.toast(text); } catch(e2) { java.copyText(text); } }
}

function checkLoginStatus() { return doCheckLogin(); }
function querySignStatus() { return doQueryStatus(); }
function doManualCheckin() { return doManual(); }
function showHelp() { return doHelp(); }

