// ===== DS 签名 =====
function md5(str) {
    try {
        var md = new Packages.java.security.MessageDigest.getInstance('MD5');
        var bytes = Packages.java.lang.String(str).getBytes('UTF-8');
        md.update(bytes);
        var digest = md.digest();
        var sb = new Packages.java.lang.StringBuilder();
        for (var i = 0; i < digest.length; i++) {
            var b = digest[i] & 0xFF;
            if (b < 16) sb.append('0');
            sb.append(Packages.java.lang.Integer.toHexString(b));
        }
        return String(sb.toString()).toLowerCase();
    } catch(e) { return ''; }
}

function getDS() {
    var t = Math.floor(Date.now() / 1000).toString();
    var r = Math.floor(Math.random() * 900000 + 100000).toString();
    var sign = md5('salt=DlOUwIupfU6YespEUWDJmXtutuXV6owG&t=' + t + '&r=' + r);
    return t + ',' + r + ',' + sign;
}

// ===== 取登录态（已存值 -> APP CookieJar） =====
function getAuth() {
    var full = '', ltoken = '', ltuid = '';
    try {
        if (typeof source !== 'undefined' && source) {
            full = String(source.get('mhyCookie') || '');
            ltoken = String(source.get('ltoken') || '');
            ltuid = String(source.get('ltuid') || '');
        }
    } catch(e) {}
    return {full: full, ltoken: ltoken, ltuid: ltuid};
}

function buildCookieHeader(auth) {
    if (auth && auth.full) return auth.full;
    if (auth && auth.ltoken && auth.ltuid) {
        return 'ltoken_v2=' + auth.ltoken + '; ltuid_v2=' + auth.ltuid +
               '; account_id=' + auth.ltuid + '; account_id_v2=' + auth.ltuid;
    }
    return '';
}

// ===== HTTP 封装 =====
function httpReq(url, method, body, auth, extra) {
    var headers = {
        'Accept': 'application/json, text/plain, */*',
        'x-rpc-channel': 'miyousheluodi',
        'Origin': 'https://webstatic.mihoyo.com',
        'x-rpc-app_version': '2.99.1',
        'User-Agent': 'Mozilla/5.0 (Linux; Android 12) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/103.0.5060.129 Mobile Safari/537.36 miHoYoBBS/2.99.1',
        'x-rpc-client_type': '5',
        'X-Requested-With': 'com.mihoyo.hyperion',
        'x-rpc-device_id': '5b814ba0-99c3-4483-0905-0007f556ee3a'
    };
    if (extra) for (var k in extra) headers[k] = extra[k];
    if (method === 'POST') headers['Content-Type'] = 'application/json';
    var cookie = buildCookieHeader(auth);
    if (cookie) headers['Cookie'] = cookie;
    var opts = {method: method, headers: headers};
    if (body) opts.body = body;
    var req = url + ',' + JSON.stringify(opts);
    return java.ajax(req);
}

// ===== 游戏配置 =====
var GAME_CONFIG = {
    '原神': {biz: 'hk4e_cn', api: 'https://api-takumi.mihoyo.com/event/luna/hk4e/', act: 'e202311201442471', signgame: 'hk4e', ref: 'https://webstatic.mihoyo.com/bbs/event/signin/hk4e/index.html'},
    '崩坏3': {biz: 'bh3_cn', api: 'https://api-takumi.mihoyo.com/event/luna/bh3/', act: 'e202306201626331', signgame: 'bh3', ref: 'https://webstatic.mihoyo.com/bbs/event/signin/bh3/index.html'},
    '崩坏星穹铁道': {biz: 'hkrpg_cn', api: 'https://api-takumi.mihoyo.com/event/luna/hkrpg/', act: 'e202304121516551', signgame: 'hkrpg', ref: 'https://webstatic.mihoyo.com/bbs/event/signin/hkrpg/index.html'},
    '绝区零': {biz: 'nap_cn', api: 'https://act-nap-api.mihoyo.com/event/luna/zzz/', act: 'e202406242138391', signgame: 'zzz', ref: 'https://webstatic.mihoyo.com/bbs/event/signin/zzz/index.html'}
};

function getRoles(auth, biz) {
    var resp = httpReq('https://api-takumi.mihoyo.com/binding/api/getUserGameRolesByCookie?game_biz=' + biz, 'GET', null, auth, {
        'DS': getDS()
    });
    if (!resp) return [];
    try {
        var data = JSON.parse(resp);
        if (data.retcode === 0 && data.data && data.data.list) return data.data.list;
    } catch(e) {}
    return [];
}

function getSignInfo(auth, cfg, region, uid) {
    var resp = httpReq(cfg.api + 'info?lang=zh-cn&act_id=' + cfg.act + '&region=' + region + '&uid=' + uid, 'GET', null, auth, {
        'DS': getDS(),
        'x-rpc-signgame': cfg.signgame,
        'Referer': cfg.ref
    });
    if (!resp) return null;
    try { return JSON.parse(resp); } catch(e) { return null; }
}

function signGame(auth, cfg, region, uid) {
    var body = JSON.stringify({act_id: cfg.act, region: String(region), uid: String(uid), lang: 'zh-cn'});
    var resp = httpReq(cfg.api + 'sign', 'POST', body, auth, {
        'DS': getDS(),
        'x-rpc-signgame': cfg.signgame,
        'Referer': cfg.ref
    });
    if (!resp) return '-1,无响应';
    try {
        var data = JSON.parse(resp);
        if (data.retcode === 0 && data.data && data.data.success === 0) return '0,签到成功';
        if (data.retcode === 0 && data.data && data.data.success === 1) return '1,触发验证码,需手动签到';
        if (data.retcode === -5003) return '0,今日已签到';
        if (data.retcode === -100) return '-1,登录失效,请重新登录';
        if (data.retcode === -500001) return '-1,请求校验失败';
        return data.retcode + ',' + (data.message || '签到失败');
    } catch(e) { return '-1,解析失败'; }
}

// ===== 主流程 =====
var games = ['原神', '崩坏3', '崩坏星穹铁道', '绝区零'];
var auth = getAuth();
if (!auth.ltoken && !auth.full) {
    java.longToast('米游社签到: 未配置Token');
    '未配置Token';
} else {
    var ok = 0, fail = 0, skip = 0;
    var lines = [];
    for (var i = 0; i < games.length; i++) {
        var name = games[i];
        var cfg = GAME_CONFIG[name];
        if (!cfg) continue;
        var roles = getRoles(auth, cfg.biz);
        if (!roles || roles.length === 0) {
            skip++;
            java.log('[' + name + '] 未绑定');
            lines.push('[' + name + '] 未绑定');
            continue;
        }
        for (var j = 0; j < roles.length; j++) {
            var r = roles[j];
            var uid = r.game_uid || r.uid;
            var rc = signGame(auth, cfg, r.region, uid);
            var msg = rc.substring(rc.indexOf(',') + 1);
            var code = rc.substring(0, rc.indexOf(','));
            java.log('[' + name + ' ' + (r.nickname || '') + '] ' + msg);
            lines.push('[' + name + ' ' + (r.nickname || '') + '] ' + msg);
            if (code === '0') ok++;
            else if (code === '1' || code === '-1') fail++;
        }
    }
    var summary = '米游社签到: 成功' + ok + ' 失败' + fail + ' 跳过' + skip;
    java.longToast(summary);
    java.log(summary);
    lines.push(summary);
    lines.join(String.fromCharCode(10));
}
